mapper.select:
SELECT id, name, gender, region, date, time
FROM tb_user
WHERE id = #{id} AND pw = #{pw}

mapper.update:
UPDATE tb_user
SET user_pw = #{pw},
    user_name = #{name},
    user_region = #{region}
WHERE user_id = #{id}

mapper.select:
SELECT COUNT(*)
FROM tb_user
WHERE user_name = #{name}
